        'top': _runs(grid[0], bg),
        'bottom': _runs(grid[-1], bg),
        'left': _runs([grid[r][0] for r in range(h)], bg),
        'right': _runs([grid[r][-1] for r in range(h)], bg),
    }
    pairs = []
    for a, b in (('top', 'bottom'), ('left', 'right')):
        for x in edges[a]:
            for y in edges[b]:
                if x[0] == y[0] and x[2] - x[1] == y[2] - y[1]:
                    pairs.append((a, x, b, y))
    if not pairs:
        return [row[:] for row in grid]
    side_a, gate_a, side_b, gate_b = max(pairs, key=lambda p: p[1][2] - p[1][1])
    wall = gate_a[0]
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != wall]
    for r, c in markers:
        color = grid[r][c]
        if side_a in ('top', 'bottom'):
            source = next(((side, gate) for side, gate in ((side_a, gate_a), (side_b, gate_b))
                           if gate[1] <= c <= gate[2]), None)
            if source is None:
                continue
            source_side, source_gate = source
            target_side, target_gate = (side_b, gate_b) if source_side == side_a else (side_a, gate_a)
            mapped_c = target_gate[1] + c - source_gate[1]
            # Ray from marker toward its own edge gate.
            step = -1 if source_side == 'top' else 1
            rr = r + step
            while 0 <= rr < h and grid[rr][c] != wall:
                if grid[rr][c] == bg:
                    out[rr][c] = color
                rr += step
            # Paired gate sends the ray into the grid toward the opposite gate.
            step = 1 if target_side == 'top' else -1
            rr = 1 if target_side == 'top' else h - 2
            while 0 <= rr < h and grid[rr][mapped_c] != wall:
                if grid[rr][mapped_c] == bg:
                    out[rr][mapped_c] = color
                rr += step
        else:
            source = next(((side, gate) for side, gate in ((side_a, gate_a), (side_b, gate_b))
                           if gate[1] <= r <= gate[2]), None)
            if source is None:
                continue
            source_side, source_gate = source
            target_side, target_gate = (side_b, gate_b) if source_side == side_a else (side_a, gate_a)
            mapped_r = target_gate[1] + r - source_gate[1]
            step = -1 if source_side == 'left' else 1
            cc = c + step
            while 0 <= cc < w and grid[r][cc] != wall:
                if grid[r][cc] == bg:
                    out[r][cc] = color
                cc += step
            step = 1 if target_side == 'left' else -1
            cc = 1 if target_side == 'left' else w - 2
            while 0 <= cc < w and grid[mapped_r][cc] != wall:
                if grid[mapped_r][cc] == bg:
                    out[mapped_r][cc] = color
                cc += step
    for r, c in markers:
        out[r][c] = 4
    return out
